-- Run with Ether stopped, after copying ether.db. Repairs Type conditions only.
BEGIN;
WITH RECURSIVE repair(viewer_id,document) AS (SELECT viewer_id,document FROM catalog_viewer_rules UNION ALL SELECT viewer_id,json_set(document,(SELECT fullkey FROM json_tree(CASE WHEN json_valid(document) THEN document ELSE '{}' END) WHERE key='value' AND value='Movies' AND json_extract(document,substr(fullkey,1,length(fullkey)-6)||'.field')='browse:type' LIMIT 1),'movie') FROM repair WHERE EXISTS(SELECT 1 FROM json_tree(CASE WHEN json_valid(document) THEN document ELSE '{}' END) WHERE key='value' AND value='Movies' AND json_extract(document,substr(fullkey,1,length(fullkey)-6)||'.field')='browse:type')) UPDATE catalog_viewer_rules SET document=(SELECT document FROM repair WHERE repair.viewer_id=catalog_viewer_rules.viewer_id AND NOT EXISTS(SELECT 1 FROM json_tree(CASE WHEN json_valid(repair.document) THEN repair.document ELSE '{}' END) WHERE key='value' AND value='Movies' AND json_extract(repair.document,substr(fullkey,1,length(fullkey)-6)||'.field')='browse:type')),revision=revision+1 WHERE EXISTS(SELECT 1 FROM json_tree(CASE WHEN json_valid(document) THEN document ELSE '{}' END) WHERE key='value' AND value='Movies' AND json_extract(document,substr(fullkey,1,length(fullkey)-6)||'.field')='browse:type');

WITH RECURSIVE repair(id,rules) AS (SELECT id,rules FROM libraries UNION ALL SELECT id,json_set(rules,(SELECT fullkey FROM json_tree(CASE WHEN json_valid(rules) THEN rules ELSE '{}' END) WHERE key='value' AND value='Movies' AND json_extract(rules,substr(fullkey,1,length(fullkey)-6)||'.field')='browse:type' LIMIT 1),'movie') FROM repair WHERE EXISTS(SELECT 1 FROM json_tree(CASE WHEN json_valid(rules) THEN rules ELSE '{}' END) WHERE key='value' AND value='Movies' AND json_extract(rules,substr(fullkey,1,length(fullkey)-6)||'.field')='browse:type')) UPDATE libraries SET rules=(SELECT rules FROM repair WHERE repair.id=libraries.id AND NOT EXISTS(SELECT 1 FROM json_tree(CASE WHEN json_valid(repair.rules) THEN repair.rules ELSE '{}' END) WHERE key='value' AND value='Movies' AND json_extract(repair.rules,substr(fullkey,1,length(fullkey)-6)||'.field')='browse:type')) WHERE EXISTS(SELECT 1 FROM json_tree(CASE WHEN json_valid(rules) THEN rules ELSE '{}' END) WHERE key='value' AND value='Movies' AND json_extract(rules,substr(fullkey,1,length(fullkey)-6)||'.field')='browse:type');

COMMIT;
